/** Normalized card record. Generated by `npm run cards:update`; never hand-edited. */
export type CardCategory = 'Leader' | 'Character' | 'Event' | 'Stage';
export type Color = 'Red' | 'Green' | 'Blue' | 'Purple' | 'Black' | 'Yellow';

export interface Artwork {
  /** Base art uses the bare card ID; alternates append a suffix such as `_p1`. */
  artworkId: string;
  imageUrls: { small?: string; large?: string };
  source: string;
}

export interface Legality {
  status: 'legal' | 'banned' | 'restricted';
  /** Copy limit when restricted; undefined means the default of four. */
  limit?: number;
}

export interface Card {
  id: string;
  name: string;
  category: CardCategory;
  colors: Color[];
  cost: number | null;
  power: number | null;
  counter: number | null;
  life: number | null;
  attributes: string[];
  types: string[];
  rarity: string;
  set: string;
  effectText: string;
  triggerText: string;
  artworks: Artwork[];
  legality: Record<string, Legality>;
  sourceUrl: string;
  fetchedAt: string;
}
